testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Condizioni e operatori",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> bool:
	var player_health: int = 15
	var is_safe: bool = player_health > 20
	return is_safe
",
   "domanda": "Quanto vale `is_safe` alla fine?",
   "spiegazione": "`player_health` è 15. La condizione `15 > 20` è falsa, quindi `is_safe` diventa `false`."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var speed: float = 350.0
	if speed > 400.0:
		return "Veloce"
	elif speed >= 350.0:
		return "Normale"
	else:
		return "Lento"
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`speed > 400.0` è falso perché 350 non è maggiore di 400. Si passa a `elif speed >= 350.0`: 350 è uguale a 350, quindi la condizione è vera e restituisce "Normale"."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var has_key: bool = true
	var score: int = 50
	var can_open: bool = has_key and score >= 100
	return can_open
",
   "domanda": "Quanto vale `can_open` alla fine?",
   "spiegazione": "Con l'operatore `and`, entrambe le parti devono essere vere. `has_key` è vero, ma `score >= 100` (50 >= 100) è falso. Il risultato dell'espressione è quindi `false`."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var position_y: float = 680.0
	if position_y >= 680.0:
		return "Reset"
	else:
		return "Continua"
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "La posizione è esattamente 680.0. La condizione usa `>=` (maggiore o uguale), quindi il controllo sul limite scatta correttamente e restituisce "Reset"."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var is_active: bool = false
	var can_spawn: bool = not is_active
	return can_spawn
",
   "domanda": "Quanto vale `can_spawn` alla fine?",
   "spiegazione": "`is_active` è `false`. L'operatore logico `not` inverte il valore booleano, trasformandolo in `true`."
  }
 ]
